check('SPACECRAFT_RESOURCE_SCHEDULING_REPAIR',identity.includes("performancePolicy='hardware-30fps-software-static-dpr1'")&&identity.includes("/SwiftShader|Software|llvmpipe/i")&&identity.includes("performanceTier=constrained?'software-static-3d':'hardware-flight-3d'")&&identity.includes("let t=constrained?.5:(now-state.flightStart)/11800")&&identity.includes("if(constrained){lastDraw=0;requestAnimationFrame(frame)}"),'software renderer uses static 3D with bounded hit redraw; hardware retains flight');
check('BRAIN_ANATOMY_PRESERVED',brain.includes("ellipsoid('cerebellum',0,-.52,-.62,.56,.255,.35")&&brain.includes("tube('midbrain'")&&brain.includes("tube('pons'")&&brain.includes("tube('medulla'")&&brain.includes("brainPosteriorBulbs:'none'")&&brain.includes("brainMaterial:'NATIVE_ROSE_FLESH_V1'"),'rose/flesh continuous anatomy preserved');
