check('CRYSTAL_GEN1525_REPAIR_PRESERVED',crystal.includes('DGB_COMPASS_CRYSTALS_SPHERICAL_CONSTELLATION_AND_CLUSTER_HARDENED_v4')&&crystal.includes('const idleHeavyFrameIntervalMs =')&&crystal.includes('state.reducedMotion\n        ? 1000\n        : 500')&&crystal.includes('registryCardinalCount:\n        4')&&crystal.includes('registryRoomCount:\n        19'),'Gen1525 crystal topology and scheduling repair retained');
