const allowed=new Set(['assets/compass/compass.identity-3d.js','assets/compass/compass.brain-scene.js','.github/ai-router/projects/compass/verify-performance-successor.mjs','.github/ai-router/projects/compass/verify-display-continuity.v1.mjs','.github/workflows/compass-performance-successor-validation.yml','.github/workflows/compass-carousel-successor-live-qualification.yml']);
const changed=git(['diff','--name-only',`${GOVERNING}...HEAD`]);
if(changed.status===0){const list=changed.stdout.trim().split(/\r?\n/).filter(Boolean);check('EXACT_GEN1526_6_PATH_BOUNDARY',list.length>0&&list.every(p=>allowed.has(p)),{changed:list});check('ONLY_TWO_PRODUCT_SURFACES_MUTATED',list.filter(p=>p.startsWith('assets/compass/')).every(p=>p==='assets/compass/compass.identity-3d.js'||p==='assets/compass/compass.brain-scene.js'),list);check('CRYSTAL_BYTE_FROZEN',!list.includes('assets/compass/compass.crystals.js'),list);}else check('EXACT_GEN1526_6_PATH_BOUNDARY',false,changed.stderr);
